<?php
declare(strict_types=1);
require_once __DIR__.'/../lib/safety_vote_phase2.php';

function sv2_campaign(int$id,bool$lock=false):?array{return db_row("SELECT c.*,v.VersionNo,v.CampaignType,v.PrivacyMode,v.TitleTh,v.TitleEn,v.Summary,v.Description,v.RulesText,v.OpenAt,v.CloseAt,v.ResultVisibility,v.PrivacyThreshold,v.MaxParticipationAttempts,v.LiveLeaderboardEnabled,v.LiveLeaderboardTopN,v.LiveLeaderboardScoreMode,v.LiveLeaderboardVisibility,v.LiveLeaderboardRefreshSeconds,v.LiveLeaderboardPrivacyThreshold,(c.Status='Open' AND (v.OpenAt IS NULL OR v.OpenAt<=NOW()) AND (v.CloseAt IS NULL OR v.CloseAt>NOW())) VotingWindowOpen,v.Status VersionStatus,v.RowVersion VersionRowVersion FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID WHERE c.id=?".($lock?' FOR UPDATE':''),[$id]);}
function sv2_active_promotion(int$campaignId):?array{try{$row=db_row("SELECT p.id,p.TitleTh titleTh,p.SubtitleTh subtitleTh,p.CtaLabel ctaLabel,p.DesktopFileID desktopFileId,p.MobileFileID mobileFileId,p.AltText altText,p.StartAt startAt,p.EndAt endAt FROM SafetyVote_Promotions p JOIN SafetyVote_Settings s ON s.SettingKey='engagement_enabled' AND s.SettingValue='1' WHERE p.CampaignID=? AND p.Status='Published' AND p.StartAt<=NOW() AND p.EndAt>NOW() ORDER BY p.Priority DESC,p.id DESC LIMIT 1",[$campaignId]);if($row){$row['id']=(int)$row['id'];$row['desktopFileId']=!empty($row['desktopFileId'])?(int)$row['desktopFileId']:null;$row['mobileFileId']=!empty($row['mobileFileId'])?(int)$row['mobileFileId']:null;}return$row;}catch(Throwable$e){if(in_array((string)$e->getCode(),['42S02','42S22'],true))return null;throw$e;}}
function sv2_questions(int$versionId):array{$qs=db_rows("SELECT id,QuestionCode questionCode,QuestionType questionType,Title title,HelpText helpText,IsRequired isRequired,MinSelections minSelections,MaxSelections maxSelections,SortOrder sortOrder FROM SafetyVote_Questions WHERE CampaignVersionID=? AND Status='Active' ORDER BY SortOrder,id",[$versionId]);foreach($qs as&$q){$q['isRequired']=(bool)$q['isRequired'];$q['minSelections']=(int)$q['minSelections'];$q['maxSelections']=(int)$q['maxSelections'];$q['options']=db_rows("SELECT o.id,o.QuestionID questionId,o.OptionCode optionCode,o.Label label,o.Description description,o.FileID fileId,o.SortOrder sortOrder,c.id candidateId,c.EmployeeID candidateEmployeeId,c.DisplayName candidateName,c.ProfileText candidateProfile FROM SafetyVote_Options o LEFT JOIN SafetyVote_Candidates c ON c.OptionID=o.id AND c.Status='Active' WHERE o.QuestionID=? AND o.Status='Active' ORDER BY o.SortOrder,o.id",[$q['id']]);}unset($q);return$qs;}
function sv2_result(array$c):array{$qs=sv2_questions((int)$c['CurrentVersionID']);$answers=db_rows("SELECT a.OptionID FROM SafetyVote_BallotAnswers a JOIN SafetyVote_Ballots b ON b.id=a.BallotID WHERE b.CampaignVersionID=? AND b.Status='Accepted'",[$c['CurrentVersionID']]);$n=db_row("SELECT (SELECT EligibleCount FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY SnapshotNo DESC LIMIT 1) eligible,(SELECT COUNT(*) FROM SafetyVote_Participation WHERE CampaignVersionID=? AND State='submitted') participated",[$c['CurrentVersionID'],$c['CurrentVersionID']])?:[];$counts=[];foreach($answers as$a)$counts[(int)$a['OptionID']]=($counts[(int)$a['OptionID']]??0)+1;$participated=(int)($n['participated']??0);foreach($qs as&$q)foreach($q['options']as&$o){$o['count']=$counts[(int)$o['id']]??0;$o['percentage']=$participated?round($o['count']/$participated*100,2):0;}unset($q,$o);$eligible=(int)($n['eligible']??0);return['eligibleCount'=>$eligible,'participationCount'=>$participated,'turnoutPct'=>$eligible?round($participated/$eligible*100,2):0,'questions'=>$qs];}
function sv2_audit(array$user,string$action,int$id,string$detail,array$meta=[]):void{sv_audit($user,$action,'SafetyVote_Campaign',(string)$id,$detail,$meta,$id,null);}
function sv2_eligibility_origin(?string$source,bool$eligible,bool$discoveryOnly=false):?string{if(!$eligible)return$discoveryOnly?'public_listing':null;$source=strtolower(trim((string)$source));if($source==='automatic_rule_match')return'automatic_rule_match';if(in_array($source,['eligibility_amendment','manual_apply','admin_approval'],true))return'admin_amendment';return'initial_snapshot';}
function sv2_readiness(array$c):array{
    $version=(int)$c['CurrentVersionID'];$questions=sv2_questions($version);
    $raw=db_rows("SELECT RuleGroup ruleGroup,RuleOrder ruleOrder,Effect effect,AttributeKey attributeKey,Operator operator,ValuesJson,Reason reason FROM SafetyVote_EligibilityRules WHERE CampaignVersionID=? AND IsActive=1 ORDER BY RuleGroup,RuleOrder,id",[$version]);
    foreach($raw as&$rule)$rule['values']=json_decode((string)$rule['ValuesJson'],true)?:[];unset($rule);
    $parsed=sv_rules($raw);$eligible=[];$currentRuleHash='';$currentRowsHash='';
    if($parsed['ok']&&$parsed['rules']){$eligible=sv_evaluate($parsed['rules'],sv_master_projection()['employees']);$currentRuleHash=sv_hash($parsed['rules']);$currentRowsHash=sv2_rows_hash($eligible);}
    $snapshot=db_row("SELECT id,SnapshotNo,RuleHash,RowsHash,EligibleCount,AccountReadyCount,WarningCount,FrozenAt FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=? AND Status='frozen' ORDER BY SnapshotNo DESC LIMIT 1",[$version]);
    $frozenRows=$snapshot?db_rows('SELECT EmployeeID employeeId,DepartmentIDSnapshot departmentId,SafetyUnitIDSnapshot safetyUnitId,PositionIDSnapshot positionId,RoleSnapshot role,TeamSnapshot team FROM SafetyVote_EligibleVoters WHERE SnapshotID=? ORDER BY EmployeeID',[$snapshot['id']]):[];
    $audienceUnchanged=(bool)($snapshot&&hash_equals(sv2_eligibility_rows_hash($frozenRows),sv2_eligibility_rows_hash($eligible)));
    $selection=['single_choice','multiple_choice','yes_no_abstain','ranking','score_allocation','token_allocation','matrix_single','matrix_multiple'];$optionsComplete=true;
    foreach($questions as$q)if(in_array($q['questionType'],$selection,true)&&count($q['options'])<2){$optionsComplete=false;break;}
    $openAt=$c['OpenAt']?:($c['ScheduledOpenAt']??null);$closeAt=$c['CloseAt']?:($c['ScheduledCloseAt']??null);$scheduleValid=$openAt&&$closeAt&&strtotime((string)$closeAt)>strtotime((string)$openAt);
    $checks=[
        ['code'=>'ACTIVE_QUESTIONS','ok'=>count($questions)>0,'detail'=>count($questions).' active question(s)'],
        ['code'=>'QUESTION_OPTIONS_COMPLETE','ok'=>$optionsComplete,'detail'=>$optionsComplete?'Choice options are complete':'A choice question has fewer than two options'],
        ['code'=>'ELIGIBILITY_RULES_VALID','ok'=>$parsed['ok']&&count($parsed['rules'])>0,'detail'=>count($parsed['rules']).' active rule(s)'],
        ['code'=>'ELIGIBILITY_FROZEN','ok'=>(bool)$snapshot,'detail'=>$snapshot?'Snapshot '.(int)$snapshot['SnapshotNo'].' frozen':'No frozen eligibility snapshot'],
        ['code'=>'ELIGIBILITY_RULES_UNCHANGED','ok'=>(bool)($snapshot&&$currentRuleHash!==''&&hash_equals((string)$snapshot['RuleHash'],$currentRuleHash)),'detail'=>'Frozen rule hash must match current rules'],
        ['code'=>'ELIGIBILITY_ROWS_UNCHANGED','ok'=>(bool)($snapshot&&$audienceUnchanged),'detail'=>'Frozen voter identity and eligibility attributes must match current master data'],
        ['code'=>'ELIGIBLE_POPULATION','ok'=>(bool)($snapshot&&(int)$snapshot['EligibleCount']>0),'detail'=>$snapshot?(int)$snapshot['EligibleCount'].' eligible voter(s)':'Eligibility not frozen'],
        ['code'=>'ELIGIBLE_ACCOUNTS_READY','ok'=>true,'advisory'=>(bool)($snapshot&&((int)$snapshot['AccountReadyCount']!==(int)$snapshot['EligibleCount']||(int)$snapshot['WarningCount']>0)),'detail'=>$snapshot?((int)$snapshot['AccountReadyCount'].'/'.(int)$snapshot['EligibleCount'].' account(s) ready; '.(int)$snapshot['WarningCount'].' warning(s). Account onboarding is informational and does not block campaign opening.'):'Account readiness is informational and does not block campaign opening'],
        ['code'=>'SCHEDULE_VALID','ok'=>(bool)$scheduleValid,'detail'=>$scheduleValid?'Open/close order is valid':'Open and close times are required in the correct order'],
        ['code'=>'PARTICIPANT_VISIBILITY','ok'=>(int)($c['IsHidden']??0)===0&&(int)($c['IsTest']??0)===0,'detail'=>((int)($c['IsHidden']??0)||(int)($c['IsTest']??0))?'Hidden/test campaigns cannot accept ballots':'Campaign is participant-visible']
    ];$blockers=array_values(array_filter($checks,fn($x)=>!$x['ok']));
    return['ready'=>!$blockers,'checks'=>$checks,'blockers'=>$blockers,'snapshot'=>$snapshot?['id'=>(int)$snapshot['id'],'snapshotNo'=>(int)$snapshot['SnapshotNo'],'eligibleCount'=>(int)$snapshot['EligibleCount'],'accountReadyCount'=>(int)$snapshot['AccountReadyCount'],'warningCount'=>(int)$snapshot['WarningCount'],'frozenAt'=>$snapshot['FrozenAt']]:null,'currentRuleHash'=>$currentRuleHash,'currentRowsHash'=>$currentRowsHash,'schedule'=>['openAt'=>$openAt?:null,'closeAt'=>$closeAt?:null,'timeZone'=>'Asia/Bangkok']];
}

function handle_safety_vote_phase2_routes(string$method,string$path):bool{
    if(strpos($path,'/safety-vote/')!==0)return false;$user=require_user();
    $builder=route_params($path,'/safety-vote/admin/campaigns/:id/builder');
    $readiness=route_params($path,'/safety-vote/admin/campaigns/:id/readiness');
    $freeze=route_params($path,'/safety-vote/admin/campaigns/:id/eligibility/freeze');
    $life=route_params($path,'/safety-vote/admin/campaigns/:id/lifecycle/:command');
    $detail=route_params($path,'/safety-vote/campaigns/:id');
    $elig=route_params($path,'/safety-vote/campaigns/:id/eligibility');
    $submit=route_params($path,'/safety-vote/campaigns/:id/ballot/submit');
    $results=route_params($path,'/safety-vote/campaigns/:id/results');
    $dashboard=route_params($path,'/safety-vote/admin/campaigns/:id/dashboard');
    $export=route_params($path,'/safety-vote/admin/campaigns/:id/exports/data');
    $matched=$builder!==null||$readiness!==null||$freeze!==null||$life!==null||$detail!==null||$elig!==null||$submit!==null||$results!==null||$dashboard!==null||$export!==null||$path==='/safety-vote/me/campaigns';
    if(!$matched)return false;sv_require_schema();
    if($submit!==null&&$method==='POST'){sv_require_permission($user,'SAFETY_VOTE_VIEW');$campaignId=(int)$submit['id'];$window=sv2_campaign($campaignId);if(!$window)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);if((int)$window['IsHidden']===1||(int)$window['IsTest']===1)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_PARTICIPATABLE','message'=>'Hidden and test campaigns cannot accept participant ballots.'],409);if((int)$window['VotingWindowOpen']!==1)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_IN_VOTING_WINDOW','message'=>'Campaign is visible but voting is not open.'],409);try{svam_auto_enroll($user,$campaignId);}catch(Throwable $error){error_log('[safety-vote] automatic eligibility reconciliation failed before ballot: '.$error->getMessage());}}
    if($builder!==null&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$c=sv2_campaign((int)$builder['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);json_response(['success'=>true,'data'=>['questions'=>sv2_questions((int)$c['CurrentVersionID'])]]);}
    if($readiness!==null&&$method==='GET'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$c=sv2_campaign((int)$readiness['id']);if(!$c)json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);try{json_response(['success'=>true,'data'=>sv2_readiness($c)]);}catch(Throwable$e){json_response(['success'=>false,'code'=>'READINESS_CHECK_FAILED','message'=>'Unable to verify authoritative campaign readiness.'],503);}}
    if($builder!==null&&$method==='PUT'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$id=sv2_int($builder['id']);$body=json_body();$fileIds=[];foreach(($body['questions']??[])as$q)foreach(($q['options']??[])as$o){$fid=sv2_int($o['fileId']??null);if($fid)$fileIds[$fid]=true;}if($fileIds){$marks=implode(',',array_fill(0,count($fileIds),'?'));$params=array_merge([$id],array_keys($fileIds));$row=db_row("SELECT COUNT(*) total FROM SafetyVote_Files WHERE CampaignID=? AND Status='Active' AND id IN ($marks)",$params);if((int)($row['total']??0)!==count($fileIds))json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Every option image must be an active private file from this campaign.'],400);}$parsed=sv2_builder($body['questions']??null);if(!$id||!$parsed['ok'])json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Question builder is invalid.','details'=>$parsed['errors']],400);$pdo=db();$pdo->beginTransaction();try{$c=sv2_campaign($id,true);if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}if($c['Status']!=='Draft'||$c['VersionStatus']!=='Draft'){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Builder is editable only in Draft.'],409);}$pdo->prepare('DELETE c FROM SafetyVote_Candidates c JOIN SafetyVote_Options o ON o.id=c.OptionID JOIN SafetyVote_Questions q ON q.id=o.QuestionID WHERE q.CampaignVersionID=?')->execute([$c['CurrentVersionID']]);$pdo->prepare('DELETE o FROM SafetyVote_Options o JOIN SafetyVote_Questions q ON q.id=o.QuestionID WHERE q.CampaignVersionID=?')->execute([$c['CurrentVersionID']]);$pdo->prepare('DELETE FROM SafetyVote_Questions WHERE CampaignVersionID=?')->execute([$c['CurrentVersionID']]);$qstmt=$pdo->prepare('INSERT INTO SafetyVote_Questions(CampaignVersionID,QuestionCode,QuestionType,Title,HelpText,IsRequired,MinSelections,MaxSelections,SortOrder,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?,?,?,?)');$ostmt=$pdo->prepare('INSERT INTO SafetyVote_Options(QuestionID,OptionCode,Label,Description,FileID,SortOrder,CreatedBy,UpdatedBy) VALUES(?,?,?,?,?,?,?,?)');foreach($parsed['questions']as$q){$qstmt->execute([$c['CurrentVersionID'],$q['questionCode'],$q['questionType'],$q['title'],$q['helpText'],$q['isRequired']?1:0,$q['minSelections'],$q['maxSelections'],$q['sortOrder'],sv_actor($user),sv_actor($user)]);$qid=(int)$pdo->lastInsertId();foreach($q['options']as$o)$ostmt->execute([$qid,$o['optionCode'],$o['label'],$o['description'],$o['fileId'],$o['sortOrder'],sv_actor($user),sv_actor($user)]);}$pdo->commit();$hash=sv2_hash($parsed['questions']);sv2_audit($user,'SAFETY_VOTE_BUILDER_UPDATE',$id,'questions='.count($parsed['questions']),['builderHash'=>$hash]);json_response(['success'=>true,'data'=>['questions'=>sv2_questions((int)$c['CurrentVersionID']),'builderHash'=>$hash]]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'BUILDER_SAVE_FAILED','message'=>'Unable to save question builder.'],500);}}
    if($freeze!==null&&$method==='POST'){sv_require_permission($user,'SAFETY_VOTE_ELIGIBILITY_MANAGE');$id=sv2_int($freeze['id']);$body=json_body();$reason=sv2_text($body['reason']??'Phase 2 preflight',500);$pdo=db();$pdo->beginTransaction();try{$c=sv2_campaign((int)$id,true);if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}if($c['Status']!=='Draft'){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Eligibility can freeze only in Draft.'],409);}$raw=db_rows("SELECT RuleGroup ruleGroup,RuleOrder ruleOrder,Effect effect,AttributeKey attributeKey,Operator operator,ValuesJson,Reason reason FROM SafetyVote_EligibilityRules WHERE CampaignVersionID=? AND IsActive=1 ORDER BY RuleGroup,RuleOrder,id",[$c['CurrentVersionID']]);foreach($raw as&$r)$r['values']=json_decode((string)$r['ValuesJson'],true)?:[];unset($r);$parsed=sv_rules($raw);if(!$parsed['ok']||!$parsed['rules']){$pdo->rollBack();json_response(['success'=>false,'code'=>'PREFLIGHT_FAILED','message'=>'At least one valid eligibility rule is required.'],422);}$master=sv_master_projection();$eligible=sv_evaluate($parsed['rules'],$master['employees']);if(!$eligible){$pdo->rollBack();json_response(['success'=>false,'code'=>'PREFLIGHT_FAILED','message'=>'Eligibility produced no voters.'],422);}$pdo->prepare("UPDATE SafetyVote_EligibilitySnapshots SET Status='superseded' WHERE CampaignVersionID=? AND Status='frozen'")->execute([$c['CurrentVersionID']]);$n=db_row('SELECT COALESCE(MAX(SnapshotNo),0)+1 no FROM SafetyVote_EligibilitySnapshots WHERE CampaignVersionID=?',[$c['CurrentVersionID']]);$ruleHash=sv_hash($parsed['rules']);$rowsHash=sv2_rows_hash($eligible);$stmt=$pdo->prepare("INSERT INTO SafetyVote_EligibilitySnapshots(CampaignVersionID,SnapshotNo,Status,RuleHash,RowsHash,EligibleCount,AccountReadyCount,WarningCount,FrozenAt,FrozenBy,Reason,CreatedBy) VALUES(?,?,'frozen',?,?,?,?,?,NOW(),?,?,?)");$stmt->execute([$c['CurrentVersionID'],$n['no'],$ruleHash,$rowsHash,count($eligible),count(array_filter($eligible,fn($e)=>$e['accountReady'])),array_sum(array_map(fn($e)=>count($e['masterWarnings']),$eligible)),sv_actor($user),$reason,sv_actor($user)]);$sid=(int)$pdo->lastInsertId();$v=$pdo->prepare('INSERT INTO SafetyVote_EligibleVoters(SnapshotID,EmployeeID,EmployeeNameSnapshot,DepartmentIDSnapshot,DepartmentNameSnapshot,SafetyUnitIDSnapshot,SafetyUnitNameSnapshot,PositionIDSnapshot,PositionNameSnapshot,RoleSnapshot,TeamSnapshot,MasterPresent,AccountReady,EligibilityState,InclusionSource,InclusionReason) VALUES(?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?)');foreach($eligible as$e)$v->execute([$sid,$e['employeeId'],$e['employeeName'],$e['departmentId'],$e['departmentName'],$e['safetyUnitId'],$e['safetyUnitName'],$e['positionId'],$e['positionName'],$e['role'],$e['team'],1,$e['accountReady']?1:0,'eligible',$e['inclusionSource'],$e['inclusionReason']]);$pdo->commit();sv2_audit($user,'SAFETY_VOTE_ELIGIBILITY_FREEZE',$id,$reason,['snapshotId'=>$sid,'eligibleCount'=>count($eligible),'ruleHash'=>$ruleHash,'rowsHash'=>$rowsHash]);json_response(['success'=>true,'data'=>['snapshotId'=>$sid,'snapshotNo'=>(int)$n['no'],'eligibleCount'=>count($eligible),'ruleHash'=>$ruleHash,'rowsHash'=>$rowsHash]],201);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'MASTER_DATA_INVALID','message'=>'Unable to freeze eligibility.'],503);}}
    if($life!==null&&$method==='POST'){sv_require_permission($user,'SAFETY_VOTE_MANAGE');$id=sv2_int($life['id']);$map=['schedule'=>'Scheduled','open'=>'Open','close'=>'Closed'];$to=$map[$life['command']]??null;if(!$id||!$to)json_response(['success'=>false,'code'=>'VALIDATION_FAILED','message'=>'Unsupported lifecycle command.'],400);$pdo=db();$pdo->beginTransaction();try{$c=sv2_campaign($id,true);if(!$c){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_FOUND','message'=>'Campaign was not found.'],404);}if(!sv2_transition($c['Status'],$to)){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_STATE_CONFLICT','message'=>'Invalid lifecycle transition.'],409);}if(in_array($to,['Scheduled','Open'],true)){$preflight=sv2_readiness($c);if(!$preflight['ready']){$pdo->rollBack();json_response(['success'=>false,'code'=>'PREFLIGHT_FAILED','message'=>'Campaign readiness has blocking items.','details'=>$preflight['blockers']],422);}$openAt=$c['OpenAt']?:$c['ScheduledOpenAt'];if($to==='Scheduled'&&strtotime((string)$openAt)<=time()){$pdo->rollBack();json_response(['success'=>false,'code'=>'SCHEDULE_NOT_FUTURE'],422);}if($to==='Open'&&strtotime((string)$openAt)>time()){$pdo->rollBack();json_response(['success'=>false,'code'=>'CAMPAIGN_NOT_DUE'],409);}}$pdo->prepare("UPDATE SafetyVote_Campaigns SET Status=?,OpenedAt=IF(?='Open',NOW(),OpenedAt),ClosedAt=IF(?='Closed',NOW(),ClosedAt),UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?")->execute([$to,$to,$to,sv_actor($user),$id]);if(in_array($to,['Scheduled','Open'],true))$pdo->prepare("UPDATE SafetyVote_CampaignVersions SET Status='Frozen',FrozenAt=COALESCE(FrozenAt,NOW()),FrozenBy=COALESCE(FrozenBy,?),ConfigHash=?,UpdatedBy=?,RowVersion=RowVersion+1 WHERE id=?")->execute([sv_actor($user),sv2_hash(sv2_questions((int)$c['CurrentVersionID'])),sv_actor($user),$c['CurrentVersionID']]);$pdo->commit();sv2_audit($user,'SAFETY_VOTE_CAMPAIGN_'.strtoupper($to),$id,'from='.$c['Status'].'; to='.$to);json_response(['success'=>true,'data'=>['id'=>$id,'status'=>$to]]);}catch(Throwable$e){if($pdo->inTransaction())$pdo->rollBack();json_response(['success'=>false,'code'=>'LIFECYCLE_FAILED','message'=>'Unable to change campaign state.'],500);}}
    if($path==='/safety-vote/me/campaigns'&&$method==='GET'){
        sv_require_permission($user,'SAFETY_VOTE_VIEW');
        $preview=sv_role($user)==='ADMIN';
        $employeeId=sv_actor($user);
        if(!$preview){
            $automaticCampaigns=db_rows("SELECT c.id FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID JOIN SafetyVote_Settings setting ON setting.SettingKey='eligibility_amendment_enabled' AND setting.SettingValue='1' LEFT JOIN (SELECT s.CampaignVersionID,s.id SnapshotID FROM SafetyVote_EligibilitySnapshots s JOIN (SELECT CampaignVersionID,MAX(SnapshotNo) SnapshotNo FROM SafetyVote_EligibilitySnapshots WHERE Status='frozen' GROUP BY CampaignVersionID) latest ON latest.CampaignVersionID=s.CampaignVersionID AND latest.SnapshotNo=s.SnapshotNo WHERE s.Status='frozen') currentSnapshot ON currentSnapshot.CampaignVersionID=c.CurrentVersionID LEFT JOIN SafetyVote_EligibleVoters currentVoter ON currentVoter.SnapshotID=currentSnapshot.SnapshotID AND currentVoter.EmployeeID=? WHERE c.Status IN ('Scheduled','Open') AND c.IsHidden=0 AND c.IsTest=0 AND v.EligibilityEnrollmentMode='automatic_rule_match' AND currentVoter.id IS NULL ORDER BY c.id LIMIT 100",[$employeeId]);
            foreach($automaticCampaigns as $automaticCampaign){try{svam_auto_enroll($user,(int)$automaticCampaign['id']);}catch(Throwable $error){error_log('[safety-vote] automatic eligibility reconciliation failed: '.$error->getMessage());}}
        }
        if($preview){
            $rows=db_rows("SELECT c.id,c.CampaignCode,c.Status,c.IsHidden,c.IsTest,c.DiscoveryMode,v.TitleTh,v.Summary,v.CampaignType,v.PrivacyMode,v.OpenAt,v.CloseAt,v.MaxParticipationAttempts,(c.Status='Open' AND c.IsHidden=0 AND c.IsTest=0 AND (v.OpenAt IS NULL OR v.OpenAt<=NOW()) AND (v.CloseAt IS NULL OR v.CloseAt>NOW())) VotingWindowOpen,p.State ParticipationState,COALESCE(p.AttemptCount,0) AttemptCount,(eligible.EmployeeID IS NULL) PreviewOnly,(eligible.EmployeeID IS NOT NULL) Eligible,0 DiscoveryOnly,eligible.InclusionSource EligibilityInclusionSource,latest.SnapshotID EligibilitySnapshotID,latest.SnapshotNo EligibilitySnapshotNo,latest.FrozenAt EligibilitySnapshotFrozenAt FROM SafetyVote_Campaigns c JOIN SafetyVote_CampaignVersions v ON v.id=c.CurrentVersionID LEFT JOIN (SELECT s.CampaignVersionID,s.id SnapshotID,s.SnapshotNo,s.FrozenAt FROM SafetyVote_EligibilitySnapshots s JOIN (SELECT CampaignVersionID,MAX(SnapshotNo) SnapshotNo FROM SafetyVote_EligibilitySnapshots WHERE Status='frozen' GROUP BY CampaignVersionID) current ON current.CampaignVersionID=s.CampaignVersionID AND current.SnapshotNo=s.SnapshotNo WHERE s.Status='frozen') latest ON latest.CampaignVersionID=v.id LEFT JOIN SafetyVote_EligibleVoters eligible ON eligible.SnapshotID=latest.SnapshotID AND eligible.EmployeeID=? LEFT JOIN SafetyVote_Participation p ON p.CampaignVersionID=v.id AND p.EmployeeID=? WHERE c.Status IN ('Scheduled','Open','Closed','Certified','Published') ORDER BY c.UpdatedAt DESC",[$employeeId,$employeeId]);
        }else{
